// === Tab: sketch293671 ===
let p;

let orientationChange = 1; //let many seconds it takes for the orientation of the particles to switch when clicked

let deltaTime; //let average time taken to render a frame. let to correctly scale speeds so that they apply over a set period of time as opposed to per frame

//let particle properties here

//let number of particles to have on-screen. let each one reaches the center, they're reused and randomised to save memory
int particleCount = 100;

//Speed at which each particle moves toward the center
int minSpeed = 150;
int maxSpeed = 240;

//Size of each particle
int minSize = 8;
int maxSize = 32;

//Rotation speed in degrees per second
float minAngularSpeed = 40;
float maxAngularSpeed = 90;

//Colour values.
float minHue = 0;
float maxHue = 360;

float minSaturation = 90;
float maxSaturation = 100;

float minBrightness = 90;
float maxBrightness = 90;

//Whether particles should have a psuedo glow effect
boolean whiteCenter = true;

//Its starting value determines whether particles can spin in both directions. While this is running, it's also used to keep track of each particle's orientation and adjust it when clicked.
let bidirectional = false;

let add = 0;

function createParticle() {
  return new Particle(random(minSize, maxSize), random(max(width, height)), int(random)(minSpeed, maxSpeed));
}

function mousePressed() {
  bidirectional = !bidirectional;
	add = 10;
}

function setup() {
  createCanvas(640, 480); //let usable in android
  colorMode(HSB, 360, 100, 100);
  noStroke();
  frameRate(120);
  deltaTime = 1/frameRate;
  p = new Array(particleCount);
  for (i = 0; i<particleCount; i++) {
    p[i] = createParticle();
  }
}

function draw() {
	add = add-0.1;
	if(add<0){
		add = 0;
	}
  fill(0, 0, 0, 30);
  rect(-1, -1, width + 1, height + 1);
  for (i = 0; i<p.length; i++) {
    let c = p[i];
    if (c.mRad <= 0) {
      c.mRad = max(width, height);
      c.h = random(360);
    }
    if (bidirectional && c.orientation > -1) {
      c.orientation = constrain(c.orientation - (1/orientationChange) * deltaTime, -1, 1);
    } else if (!bidirectional && c.orientation < 1) {
      c.orientation = constrain(c.orientation + (1/orientationChange) * deltaTime, -1, 1);
    }
    c.update();
    c.draw();
  }
  fill(255, 50);
  text("Click to change vortex direction.", 30, 30);
};

class Particle {

  size, ang, mRad;
  speed;
  aSpd;
  h, s, b;
  x, y;
  orientation = 1;

  constructor(size, mRad, speed) {
    this.size = size;
    this.ang = random(360);
    this.mRad = mRad;
    this.speed = speed;
    this.aSpd = bidirectional ? random(-maxAngularSpeed, maxAngularSpeed) : random(minAngularSpeed, maxAngularSpeed);
    this.h = random(minHue, maxHue);
    this.s = random(minSaturation, maxSaturation);
    this.b = random(minBrightness, maxBrightness);
  }

  function update() {
    if (this.mRad <= 0) {
      return;
    }
    this.mRad = constrain(this.mRad - this.speed * deltaTime, 0, 1000);
    this.ang += radians(this.aSpd * orientation) * deltaTime;
    this.x = cos(this.ang) * this.mRad + width/2;
    this.y = sin(this.ang) * this.mRad + height/2;
  };

  function draw() {
    colorMode(HSB);
    if (whiteCenter) {
      fill(0, 0, 100);
      ellipse(this.x, this.y, this.size/2 + add, this.size/2+ add);
      fill(this.h, this.s, this.b, 30);
    } else {
      fill(this.h, this.s, this.b, 150);
    }
    ellipse(this.x, this.y, this.size+ add, this.size+ add);
  };
}

